<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Coin, CreditCard, Trophy } from '@element-plus/icons-vue'
import { api } from '@/api/client'
interface Inspection{id:number;date:string;score:number;level:string;items:Record<string,number>;comment:string}
interface Utility{month:string;electricity:number;water:number;amount:number;status:string}
interface Recharge{id:number;orderNo:string;amount:number;paymentMethod:string;status:string;createdAt:string}
interface Transaction{id:number;month:string;amount:number;status:string;createdAt:string}
interface Account{balance:number;records:Recharge[];transactions:Transaction[]}
const inspections=ref<Inspection[]>([]),utilities=ref<Utility[]>([]),account=ref<Account>({balance:0,records:[],transactions:[]})
const active=ref<'卫生记录'|'水电查询'>('卫生记录'),rechargeVisible=ref(false),submitting=ref(false),paying=ref(false),customAmount=ref('')
const recharge=reactive({amount:50,paymentMethod:'微信支付'})
async function load(){[inspections.value,utilities.value,account.value]=await Promise.all([api.get<Inspection[]>('/api/student/inspections'),api.get<Utility[]>('/api/student/utilities'),api.get<Account>('/api/student/utility-account')])}
function openRecharge(){recharge.amount=50;recharge.paymentMethod='微信支付';customAmount.value='';rechargeVisible.value=true}
function chooseAmount(value:number){recharge.amount=value;customAmount.value=''}
function useCustom(){if(!customAmount.value.trim())return;const value=Number(customAmount.value);if(Number.isFinite(value))recharge.amount=value}
async function submitRecharge(){useCustom();if(recharge.amount<10||recharge.amount>500)return ElMessage.warning('请输入 10—500 元的充值金额');submitting.value=true;try{await api.post('/api/student/utility-recharges',recharge);ElMessage.success('充值成功');rechargeVisible.value=false;await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'充值失败')}finally{submitting.value=false}}
async function payBill(){const bill=utilities.value[0];if(!bill||bill.status==='已缴费')return ElMessage.info('本月账单已缴清');try{await ElMessageBox.confirm(`将从水电余额中支付 ¥${bill.amount}，是否继续？`,'确认缴费',{confirmButtonText:'确认支付',cancelButtonText:'取消'});paying.value=true;await api.post(`/api/student/utilities/${bill.month}/pay`);ElMessage.success('本月水电费缴纳成功');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'缴费失败')}finally{paying.value=false}}
onMounted(load)
</script>
<template><div><div class="student-page-head"><span>DORM LIFE</span><h1>宿舍生活</h1><p>查看卫生检查、水电用量、账户余额和缴费记录。</p></div><div class="life-tabs"><button :class="{active:active==='卫生记录'}" @click="active='卫生记录'"><el-icon><Trophy/></el-icon>卫生记录</button><button :class="{active:active==='水电查询'}" @click="active='水电查询'"><el-icon><Coin/></el-icon>水电查询</button></div>
<template v-if="active==='卫生记录'"><section class="score-overview"><div class="big-score"><strong>{{inspections[0]?.score}}</strong><span>最新得分</span></div><div><span>本学期平均</span><strong>89.0</strong><small>超过 82% 的宿舍</small></div><div><span>楼栋排名</span><strong>12 <i>/ 120</i></strong><small>较上周上升 3 名</small></div><div><span>检查次数</span><strong>{{inspections.length}}</strong><small>本学期累计</small></div></section><section class="student-card record-list"><header><h2>检查记录</h2><span>满分 100 分</span></header><article v-for="item in inspections" :key="item.id"><div><strong>{{item.date}}</strong><span>{{item.comment}}</span></div><b>{{item.score}}</b><em>{{item.level}}</em></article></section></template>
<template v-else><section class="utility-hero"><div><span>水电账户余额</span><strong>¥ {{account.balance.toFixed(2)}}</strong><small>本月账单 ¥{{utilities[0]?.amount}} · 用电 {{utilities[0]?.electricity}} 度 · 用水 {{utilities[0]?.water}} 吨</small></div><div><button class="ghost" @click="openRecharge"><el-icon><CreditCard/></el-icon>账户充值</button><button :disabled="paying||utilities[0]?.status==='已缴费'" @click="payBill">{{utilities[0]?.status==='已缴费'?'本月已缴清':'余额缴费'}}</button></div></section><div class="utility-grid"><section class="student-card"><header><h2>每月水电账单</h2><span>最近 3 个月</span></header><table><thead><tr><th>月份</th><th>用电量</th><th>用水量</th><th>金额</th><th>状态</th></tr></thead><tbody><tr v-for="item in utilities" :key="item.month"><td>{{item.month}}</td><td>{{item.electricity}} 度</td><td>{{item.water}} 吨</td><td>¥{{item.amount}}</td><td><b :class="{pending:item.status==='待缴费'}">{{item.status}}</b></td></tr></tbody></table></section><section class="student-card"><header><h2>账户流水</h2><button @click="openRecharge">充值</button></header><div class="flows"><article v-for="item in account.records" :key="item.id"><i>+</i><div><strong>充值 ¥{{item.amount.toFixed(2)}}</strong><span>{{item.paymentMethod}} · {{item.createdAt}}</span></div><b>成功</b></article><article v-for="item in account.transactions" :key="item.id"><i class="out">−</i><div><strong>水电缴费 ¥{{Math.abs(item.amount).toFixed(2)}}</strong><span>{{item.month}} · {{item.createdAt}}</span></div><b>成功</b></article><p v-if="!account.records.length&&!account.transactions.length">暂无账户流水</p></div></section></div></template>
<el-dialog v-model="rechargeVisible" title="水电账户充值" width="min(520px,92vw)"><div class="recharge-form"><div class="balance-card"><span>当前余额</span><strong>¥ {{account.balance.toFixed(2)}}</strong><small>充值成功后实时到账</small></div><label>选择充值金额</label><div class="amount-grid"><button v-for="value in [20,50,100,200]" :key="value" :class="{active:recharge.amount===value&&!customAmount}" @click="chooseAmount(value)">¥{{value}}</button></div><label>自定义金额</label><div class="custom-amount"><span>¥</span><input v-model="customAmount" inputmode="decimal" placeholder="10—500" @input="useCustom"/></div><label>支付方式</label><div class="payment-methods"><button v-for="method in ['微信支付','支付宝','校园卡']" :key="method" :class="{active:recharge.paymentMethod===method}" @click="recharge.paymentMethod=method">{{method}}</button></div><div class="secure-tip">演示系统将模拟支付成功，并生成可查询的充值流水。</div></div><template #footer><el-button @click="rechargeVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitRecharge">确认充值 ¥{{recharge.amount}}</el-button></template></el-dialog></div></template>
<style scoped>.student-page-head{margin-bottom:18px}.student-page-head>span{color:#198075;font-size:8px;letter-spacing:1.4px}.student-page-head h1{margin:5px 0;font-size:25px}.student-page-head p{margin:0;color:#82908c;font-size:11px}.life-tabs{margin-bottom:16px;padding:5px;border:1px solid #e1e7e4;border-radius:10px;display:inline-flex;background:white}.life-tabs button{height:34px;padding:0 15px;border:0;border-radius:7px;display:flex;align-items:center;gap:6px;color:#71807c;background:transparent;font-size:10px}.life-tabs button.active{color:#14766c;background:#e8f5f2;font-weight:600}.score-overview{margin-bottom:16px;display:grid;grid-template-columns:1.2fr repeat(3,1fr);gap:12px}.score-overview>div{min-height:110px;padding:19px;border:1px solid #e1e7e4;border-radius:13px;display:grid;background:white}.score-overview span{color:#7f8d89;font-size:9px}.score-overview strong{align-self:center;font-size:22px}.score-overview small{color:#99a3a0;font-size:8px}.score-overview strong i{color:#9ca5a2;font-size:10px;font-style:normal}.big-score{color:white!important;background:linear-gradient(130deg,#12766d,#2a9889)!important}.big-score span{color:#b0dcd5}.student-card{border:1px solid #e1e7e4;border-radius:14px;background:white}.student-card header{height:60px;padding:0 20px;border-bottom:1px solid #edf0ef;display:flex;align-items:center;justify-content:space-between}.student-card h2{margin:0;font-size:14px}.student-card header span{color:#8c9894;font-size:9px}.record-list article{padding:15px 20px;border-top:1px solid #edf0ef;display:flex;align-items:center;gap:15px}.record-list article>div{display:grid;gap:4px;flex:1}.record-list article span{color:#84918d;font-size:9px}.record-list article>b{color:#15766c;font-size:22px}.record-list article>em{color:#6f7d79;font-size:9px;font-style:normal}.utility-hero{margin-bottom:16px;padding:24px 28px;border-radius:15px;display:flex;align-items:center;justify-content:space-between;color:white;background:linear-gradient(120deg,#23475c,#35738a)}.utility-hero>div:first-child{display:grid;gap:5px}.utility-hero span,.utility-hero small{color:#aecbd4;font-size:9px}.utility-hero strong{font-size:30px}.utility-hero>div:last-child{display:flex;gap:8px}.utility-hero button{height:36px;padding:0 13px;border:0;border-radius:7px;color:#28566a;background:white;font-size:9px}.utility-hero button.ghost{border:1px solid rgba(255,255,255,.4);display:flex;align-items:center;gap:5px;color:white;background:rgba(255,255,255,.1)}.utility-hero button:disabled{opacity:.55}.utility-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:15px}.student-card table{width:100%;border-collapse:collapse;font-size:9px}.student-card th,.student-card td{padding:14px 18px;border-top:1px solid #edf0ef;text-align:left}.student-card th{color:#899591;background:#fafbfb}.student-card td b{color:#27816f}.student-card td b.pending{color:#b97824}.student-card header button{height:29px;padding:0 10px;border:1px solid #cde2de;border-radius:6px;color:#16766b;background:#f0f8f6;font-size:8px}.flows article{padding:13px 16px;border-top:1px solid #edf0ef;display:flex;align-items:center;gap:9px}.flows article>i{width:28px;height:28px;border-radius:7px;display:grid;place-items:center;color:#18806f;background:#e9f5f2;font-style:normal}.flows article>i.out{color:#b87727;background:#fff3e3}.flows article>div{min-width:0;display:grid;gap:3px;flex:1}.flows strong{font-size:9px}.flows span{overflow:hidden;color:#8a9692;font-size:7px;text-overflow:ellipsis;white-space:nowrap}.flows article>b{color:#198070;font-size:8px}.flows>p{padding:35px;text-align:center;color:#919c98;font-size:9px}.recharge-form{display:grid;gap:12px}.balance-card{padding:16px;border-radius:10px;display:grid;gap:4px;color:white;background:linear-gradient(120deg,#1c6f68,#30988b)}.balance-card span,.balance-card small{color:#b9ded8;font-size:8px}.balance-card strong{font-size:23px}.recharge-form>label{font-size:10px;font-weight:600}.amount-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.amount-grid button,.payment-methods button{height:42px;border:1px solid #dfe5e3;border-radius:8px;color:#4d5d58;background:white}.amount-grid button.active,.payment-methods button.active{border-color:#278c80;color:#0e746a;background:#edf8f5}.custom-amount{height:42px;padding:0 12px;border:1px solid #dfe5e3;border-radius:8px;display:flex;align-items:center;gap:8px}.custom-amount input{flex:1;border:0;outline:0}.payment-methods{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.secure-tip{padding:9px 11px;border-radius:7px;color:#7b8783;background:#f4f7f6;font-size:8px}@media(max-width:720px){.score-overview{grid-template-columns:1fr 1fr}.utility-grid{grid-template-columns:1fr}.utility-hero{align-items:flex-start;gap:16px;flex-direction:column}}</style>
